function localizeUI(root,language){const pairs=language==='hi'?Object.entries(hindiUI):Object.entries(hindiUI).map(([en,hi])=>[hi,en]);const replace=value=>pairs.sort((a,b)=>b[0].length-a[0].length).reduce((text,[from,to])=>text.split(from).join(to),value);const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{const next=replace(node.nodeValue);if(next!==node.nodeValue)node.nodeValue=next});root.querySelectorAll('[placeholder],[aria-label]').forEach(element=>['placeholder','aria-label'].forEach(attribute=>{const value=element.getAttribute(attribute);if(value){const next=replace(value);if(next!==value)element.setAttribute(attribute,next)}}))}
function App(){
 const [lang,setLang]=useState('en'),[view,setView]=useState('home'),[lots,setLots]=useState(initialLots),[cart,setCart]=useState([]),[wishlist,setWishlist]=useState([]),[selectedLot,setSelectedLot]=useState(null),[modal,setModal]=useState(null),[toast,setToast]=useState(''),[session,setSession]=useState(null),[produceRequests,setProduceRequests]=useState([]),[orders,setOrders]=useState([]),[bulkRequests,setBulkRequests]=useState([]),[logisticsJobs,setLogisticsJobs]=useState([]),[warehouses,setWarehouses]=useState([{name:'Jaipur North',address:'Jaipur North, Rajasthan'},{name:'Sanganer Hub',address:'Sanganer, Jaipur, Rajasthan'}]),[liveTick,setLiveTick]=useState(0); const t=translations[lang];
 useEffect(()=>{if(!isSupabaseConfigured)return;supabase.auth.getSession().then(async({data:{session:authSession}})=>{if(!authSession)return;const {data:profile}=await supabase.from('profiles').select('role,full_name,farmer_id').eq('id',authSession.user.id).single();if(profile)setSession({role:profile.role,label:profile.full_name,name:profile.full_name,farmerId:profile.farmer_id,userId:authSession.user.id})})},[]);
 useEffect(()=>{if(!isSupabaseConfigured||!session?.userId)return;supabase.from('produce_lots').select('id,lot_code,crop,grade,quantity_kg,price_per_kg,warehouses(name)').then(({data})=>{if(data)setLots(data.map((lot,index)=>({id:lot.lot_code,dbId:lot.id,crop:lot.crop,hi:lot.crop,grade:lot.grade,qty:Number(lot.quantity_kg),price:Number(lot.price_per_kg),old:1,warehouse:lot.warehouses?.name||'Warehouse',farmer:'',dist:'Nearby',trend:index===0?8:3})))})},[session?.userId,liveTick]);
 useEffect(()=>{if(!isSupabaseConfigured||!session?.userId)return;supabase.from('farmer_listings').select('id,farmer_id,crop,category,description,quantity_kg,price_per_kg,image_url').eq('status','published').then(({data})=>{if(data)setLots(current=>[...current.filter(lot=>!lot.listing),...data.map((listing,index)=>({id:'LIST-'+listing.id.slice(-6).toUpperCase(),listing:true,listingId:listing.id,farmerId:listing.farmer_id,crop:listing.crop,hi:listing.crop,grade:'Farmer listed',qty:Number(listing.quantity_kg),price:Number(listing.price_per_kg),old:0,warehouse:'Direct farmer listing',farmer:'Verified farmer',dist:'Direct',trend:0,imageUrl:listing.image_url,description:listing.description,category:listing.category}))])})},[session?.userId,liveTick]);
 useEffect(()=>{if(!isSupabaseConfigured||!session?.userId)return;supabase.from('warehouses').select('id,name,address').eq('active',true).order('name').then(({data})=>{if(data?.length)setWarehouses(data)})},[session?.userId,liveTick]);
 useEffect(()=>{if(!isSupabaseConfigured||!session?.userId)return;const requestQuery=(session.role==='admin'?supabase.from('produce_requests').select('id,crop,gross_weight_kg,collection_cluster,request_type,status,profiles(full_name)'):supabase.from('produce_requests').select('id,crop,gross_weight_kg,collection_cluster,request_type,status').eq('farmer_id',session.userId)).order('created_at',{ascending:false});requestQuery.then(({data})=>{if(data)setProduceRequests(data.map(r=>({id:r.id,crop:r.crop,grossWeight:Number(r.gross_weight_kg),cluster:r.collection_cluster,type:r.request_type==='cluster_collection'?'Cluster collection request':'Produce intake',status:r.status,farmer:r.profiles?.full_name||session.name||'Farmer'})))})},[session?.userId,session?.role,liveTick]);
 useEffect(()=>{if(!isSupabaseConfigured||!session?.userId)return;const query=(session.role==='admin'?supabase.from('consumer_orders').select('id,order_code,total_kg,status,warehouses(name),profiles(full_name,address)'):supabase.from('consumer_orders').select('id,order_code,total_kg,status,warehouses(name)').eq('consumer_id',session.userId)).order('created_at',{ascending:false});query.then(({data})=>{if(data)setOrders(data.map(order=>({dbId:order.id,id:order.order_code,quantity:Number(order.total_kg),items:0,status:order.status.replaceAll('_',' '),pickupWarehouse:order.warehouses?.name||'Warehouse',consumerName:order.profiles?.full_name||session.name||'Consumer',consumerAddress:order.profiles?.address||'Address not available'})))})},[session?.userId,session?.role,liveTick]);
 useEffect(()=>{if(!isSupabaseConfigured||session?.role!=='admin')return;supabase.from('bulk_requests').select('id,crop,quantity_kg,status,buyer_name,created_at').order('created_at',{ascending:false}).then(({data})=>{if(data)setBulkRequests(data) });supabase.from('logistics_jobs').select('id,source_type,status,details,created_at').order('created_at',{ascending:false}).then(({data})=>{if(data)setLogisticsJobs(data)})},[session?.role,liveTick]);
 useEffect(()=>{if(!isSupabaseConfigured||session?.role!=='admin')return;const channel=supabase.channel('admin-live-operations').on('postgres_changes',{event:'*',schema:'public',table:'produce_requests'},()=>setLiveTick(tick=>tick+1)).on('postgres_changes',{event:'*',schema:'public',table:'consumer_orders'},()=>setLiveTick(tick=>tick+1)).on('postgres_changes',{event:'*',schema:'public',table:'bulk_requests'},()=>setLiveTick(tick=>tick+1)).on('postgres_changes',{event:'*',schema:'public',table:'bulk_quotes'},()=>setLiveTick(tick=>tick+1)).on('postgres_changes',{event:'*',schema:'public',table:'logistics_jobs'},()=>setLiveTick(tick=>tick+1)).subscribe();return()=>supabase.removeChannel(channel)},[session?.role]);
 useEffect(()=>{const root=document.body;if(!root)return;let pending=false;const translate=()=>{if(!pending){pending=true;localizeUI(root,lang);pending=false}};translate();const observer=new MutationObserver(translate);observer.observe(root,{childList:true,subtree:true,characterData:true});return()=>observer.disconnect()},[lang,view]);
 const notify=m=>{setToast(m);setTimeout(()=>setToast(''),3000)};
 const reserve=(lot,quantity=10)=>{const remaining=Math.max(0,50-cart.reduce((sum,item)=>sum+(item.selectedQty||10),0));if(!remaining){notify('A pickup order is limited to 50 kg. Complete checkout or remove an item first.');return}const safeQuantity=Math.max(1,Math.min(50,remaining,Number(quantity)||10,lot.qty));if(lot.listing){notify('This farmer photo listing is visible now; warehouse intake will enable checkout after stock verification.');return}setCart(c=>[...c,{...lot,selectedQty:safeQuantity}]);setLots(ls=>ls.map(x=>x.id===lot.id?{...x,qty:x.qty-safeQuantity}:x));notify(safeQuantity+' kg reserved. Your order is ready for checkout.');};
 const placeOrder=async(pickupWarehouse)=>{const id=`ORD-${String(Date.now()).slice(-6)}`;const order={id,pickupWarehouse,items:cart.length,quantity:cart.reduce((sum,lot)=>sum+(lot.selectedQty||10),0),status:'Ready for pickup',consumerName:session?.name||'Consumer',consumerAddress:'Address stored securely'};if(isSupabaseConfigured&&session?.userId){const {data:warehouse,error:warehouseError}=await supabase.from('warehouses').select('id').eq('name',pickupWarehouse).single();if(warehouseError){notify('Pickup warehouse could not be found.');return}const {data:created,error}=await supabase.from('consumer_orders').insert({order_code:id,consumer_id:session.userId,pickup_warehouse_id:warehouse.id,total_kg:order.quantity,total_amount:cart.reduce((sum,lot)=>sum+lot.price*(lot.selectedQty||10),0)}).select('id').single();if(error){notify(error.message);return}const items=cart.filter(lot=>lot.dbId).map(lot=>({order_id:created.id,lot_id:lot.dbId,quantity_kg:lot.selectedQty||10,unit_price:lot.price}));if(items.length){const {error:itemError}=await supabase.from('order_items').insert(items);if(itemError){notify(itemError.message);return}}const {data:job,error:jobError}=await supabase.from('logistics_jobs').insert({requested_by:session.userId,source_type:'consumer_pickup',source_id:created.id,details:'Pickup order '+id+' at '+pickupWarehouse}).select('id').single();if(jobError)throw jobError;await supabase.from('logistics_routes').insert({job_id:job.id,created_by:session.userId,route_type:'warehouse_to_consumer',origin:pickupWarehouse,destination:'Consumer pickup point',stops:JSON.stringify([pickupWarehouse,'Consumer pickup point'])})}setOrders(existing=>[order,...existing]);setCart([]);setModal(null);notify(`Order ${id} confirmed. Pickup: ${pickupWarehouse}.`);};
 const access=(role,destination)=>{if(session?.role===role||session?.role==='admin')setView(destination);else {setView('auth');notify(`Please sign in as ${role}.`)}};
 const logout=async()=>{if(isSupabaseConfigured)await supabase.auth.signOut();setSession(null);setCart([]);setModal(null);setView('home');notify('You have logged out.');};
 const total=cart.reduce((sum,lot)=>sum+(lot.selectedQty||10),0);
 return <><header><button className="brand" onClick={()=>setView('home')}><span><Sprout size={24}/></span>Farm<span>Link</span></button><nav><button onClick={()=>access('consumer','market')}>Marketplace</button><button onClick={()=>access('consumer','bulk')}>Wholesale</button><button onClick={()=>access('admin','warehouse')}>Warehouse</button><button onClick={()=>access('farmer','farmer')}>Farmer</button></nav><div className="head-actions"><button className="language" onClick={()=>setLang(lang==='en'?'hi':'en')}><Languages size={16}/>{lang==='en'?'हिंदी':'English'}</button>{session?<button className="profile-btn" onClick={()=>session.role==='admin'?setView('admin'):setView(session.role==='farmer'?'farmer':'consumer')}><UserRound size={17}/>{session.label}</button>:<button className="login-btn" onClick={()=>setView('auth')}><UserRound size={17}/>Sign in</button>}<span className="logout-wrap">{session&&<button className="login-btn" onClick={logout}><LogOut size={17}/>Logout</button>}</span><button className="cart" onClick={()=>access('consumer','consumer')}><ShoppingCart size={18}/>{cart.length||''}</button></div></header>
 <main>{view==='home'&&<Home t={t} lots={lots} setView={setView} access={access} reserve={reserve} setModal={setModal}/>} {view==='market'&&<Market lots={lots} reserve={reserve} cart={cart} total={total} onCheckout={()=>setModal('checkout')} notify={notify} wishlist={wishlist} setWishlist={setWishlist} setSelectedLot={setSelectedLot} setView={setView}/>} {view==='detail'&&<ProductDetail lot={selectedLot} reserve={reserve} wishlist={wishlist} setWishlist={setWishlist} setView={setView} notify={notify}/>} {view==='consumer'&&<ConsumerHub cart={cart} wishlist={wishlist} lots={lots} orders={orders} setView={setView} notify={notify}/>} {view==='bulk'&&<BulkMarket lots={lots} setView={setView} notify={notify} session={session} setLiveTick={setLiveTick}/>} {view==='warehouse'&&<WarehouseView session={session} lots={lots} setLots={setLots} produceRequests={produceRequests} orders={orders} warehouses={warehouses} setWarehouses={setWarehouses} setLiveTick={setLiveTick} notify={notify}/>} {view==='farmer'&&<FarmerView session={session} lots={lots} setModal={setModal} produceRequests={produceRequests} setProduceRequests={setProduceRequests} notify={notify}/>} {view==='auth'&&<AuthView setSession={setSession} setView={setView} notify={notify}/>} {view==='admin'&&<AdminView session={session} warehouses={warehouses} lots={lots} orders={orders} produceRequests={produceRequests} bulkRequests={bulkRequests} logisticsJobs={logisticsJobs} setLiveTick={setLiveTick} setView={setView} logout={logout} notify={notify}/>}</main>
 <footer><div className="brand light"><span><Sprout size={22}/></span>Farm<span>Link</span></div><p>Farmer-first aggregation • Transparent grade • Better choices</p><small>Demo platform for SIH 2026 PS 26033. AI recommendations are illustrative, not guarantees.</small></footer>
 {modal==='voice'&&<Voice close={()=>setModal(null)} notify={notify} session={session}/>} {modal==='ai'&&<AI close={()=>setModal(null)}/>} {modal==='checkout'&&<Checkout cart={cart} warehouses={warehouses} close={()=>setModal(null)} placeOrder={placeOrder}/>} {toast&&<div className="toast"><Check size={17}/>{toast}</div>}</>}

function Home({t,lots,setView,access,reserve,setModal}){return <><section className="hero"><div className="hero-copy"><p className="eyebrow"><Leaf size={15}/>{t.tag}</p><h1>{t.hero}</h1><p>{t.sub}</p><div className="cta"><button className="primary" onClick={()=>access('consumer','market')}>{t.shop}<ArrowUpRight size={18}/></button><button className="secondary" onClick={()=>access('farmer','farmer')}>{t.farmer}<ChevronRight size={18}/></button></div><div className="trust"><span><ShieldCheck/>Traceable lots</span><span><ScanLine/>Human-verified grades</span></div></div><div className="hero-card"><div className="sun"></div><div className="field"><span></span><span></span><span></span></div><div className="floating price"><small>MARKET SIGNAL</small><b>Tomato +8%</b><em>High demand nearby</em></div><div className="floating stock"><PackageCheck/><div><b>2,510 kg</b><small>available today</small></div></div><div className="produce tomato">●</div><div className="produce onion">●</div></div></section>
 <section className="section"><div className="section-head"><div><p className="eyebrow green">LIVE FROM NEARBY WAREHOUSES</p><h2>{t.stock}</h2></div><button className="text-btn" onClick={()=>access('consumer','market')}>View marketplace <ArrowUpRight size={16}/></button></div><div className="cards">{lots.map(l=><LotCard key={l.id} lot={l} onClick={(lot,quantity)=>reserve(lot,quantity)}/>)}</div></section>
 <section className="impact"><div><p className="eyebrow">ONE CONNECTED FLOW</p><h2>Less uncertainty.<br/>More choice.</h2><p>FarmLink joins physical aggregation with market intelligence so produce moves with clarity, not pressure.</p><button className="outline" onClick={()=>setModal('ai')}><BrainCircuit size={18}/>{t.ai}</button></div><div className="flow"><Flow n="1" icon={<Truck/>} title="Cluster pickup" text="Village & FPO collection"/><Flow n="2" icon={<Warehouse/>} title="Warehouse intake" text="Weigh, grade & store"/><Flow n="3" icon={<BrainCircuit/>} title="AI guidance" text="Price, demand & stock-age"/><Flow n="4" icon={<ShoppingCart/>} title="Market access" text="Consumer & bulk buyers"/></div></section>
 <section className="voice-banner"><div className="mic"><Mic size={34}/></div><div><p className="eyebrow">{t.voice.toUpperCase()}</p><h2>Ask in your own language.</h2><p>Call, speak, and get guided help with stock, prices or pickups.</p></div><button className="primary pale" onClick={()=>setModal('voice')}>Try voice demo <Mic size={18}/></button></section></>}
function LotCard({lot,onClick}){const [quantity,setQuantity]=useState(10);const selected=Math.min(50,Math.max(1,Number(quantity)||1));const available=Math.min(selected,lot.qty);return <article className="lot"><div className={'lot-img '+lot.crop.toLowerCase()}>{lot.imageUrl?<img src={lot.imageUrl} alt={lot.crop+' grown by '+lot.farmer}/>:<span className="produce-placeholder">{lot.crop}</span>}<b>{lot.listing?'Farmer photo':'Grade '+lot.grade}</b></div><div className="lot-body"><div className="lot-title"><div><h3>{lot.crop}</h3><p><MapPin size={14}/>{lot.warehouse} · {lot.dist}</p></div><span className={lot.trend>=0?'up':'down'}>{lot.trend>=0?'↑':''}{lot.trend}%</span></div><div className="lot-meta"><span>{lot.qty} kg available</span><span><Clock3 size={14}/>{lot.old} day old</span></div><div className="buy"><b>₹{lot.price}<small>/kg</small></b><label className="quantity-picker"><span>kg</span><input aria-label={'Kilograms of '+lot.crop} type="number" min="1" max="50" value={quantity} onChange={e=>setQuantity(Math.min(50,Math.max(1,Number(e.target.value)||1)))}/></label><button disabled={lot.qty<1} onClick={()=>onClick(lot,available)}>Add {available} kg</button></div></div></article>}
function Flow({n,icon,title,text}){return <div className="flow-item"><span>{n}</span><i>{icon}</i><div><b>{title}</b><small>{text}</small></div></div>}
function Market({lots,reserve,cart,total,onCheckout,notify,wishlist,setWishlist,setSelectedLot,setView}){
 const [crop,setCrop]=useState(''),[grade,setGrade]=useState(''),[sort,setSort]=useState('smart'),[query,setQuery]=useState('');
 const cropOptions=useMemo(()=>[...new Set(lots.map(l=>l.crop).filter(Boolean))].sort(),[lots]);
 const gradeOptions=useMemo(()=>[...new Set(lots.map(l=>l.grade).filter(Boolean))].sort(),[lots]);
 const visible=useMemo(()=>lots.filter(l=>{const searchable=[l.crop,l.category,l.farmer,l.warehouse,l.grade].filter(Boolean).join(' ').toLowerCase();return (!crop||l.crop===crop)&&(!grade||l.grade===grade)&&(!query||searchable.includes(query.toLowerCase()))}).sort((a,b)=>sort==='price'?a.price-b.price:sort==='distance'?(parseInt(a.dist)||999)-(parseInt(b.dist)||999):(b.trend*3+b.qty/100-b.price/10)-(a.trend*3+a.qty/100-a.price/10)),[lots,crop,grade,sort,query]);
 const favorite=lot=>{setWishlist(items=>items.some(x=>x.id===lot.id)?items.filter(x=>x.id!==lot.id):[...items,lot]);notify(wishlist.some(x=>x.id===lot.id)?'Removed from wishlist.':'Saved to wishlist.');};
 return <section className="page"><div className="page-top"><div><p className="eyebrow green">FRESH PRODUCE MARKETPLACE</p><h1>Local market, live stock.</h1><p>Smart-ranked by quality, proximity and price competitiveness. Every live lot has a traceable quality record.</p></div><div className="checkout"><b>{cart.length} items · {total} kg</b><button className="primary" disabled={!cart.length} onClick={onCheckout}>Checkout</button></div></div><div className="market-tools"><input aria-label="Search produce" placeholder="Search produce, farmer or location" value={query} onChange={e=>setQuery(e.target.value)}/><select aria-label="Crop selection" value={crop} onChange={e=>setCrop(e.target.value)}><option value="">All crops</option>{cropOptions.map(name=><option key={name} value={name}>{name}</option>)}</select><select aria-label="Grade filter" value={grade} onChange={e=>setGrade(e.target.value)}><option value="">All grades</option>{gradeOptions.map(name=><option key={name} value={name}>{name}</option>)}</select><select aria-label="Sort marketplace listings" value={sort} onChange={e=>setSort(e.target.value)}><option value="smart">AI smart ranking</option><option value="price">Lowest price</option><option value="distance">Nearest first</option></select></div><p className="search-note"><BrainCircuit size={16}/> Crop selection, grade and search work together. AI ranking considers verified grade, distance, price and stock freshness.</p><div className="cards">{visible.map(l=><div className="product-wrap" key={l.id}><LotCard lot={l} onClick={(lot,quantity)=>reserve(lot,quantity)}/><div className="product-actions"><button onClick={()=>{setSelectedLot(l);setView('detail')}}>Quality report</button><button className={wishlist.some(x=>x.id===l.id)?'favorite active':'favorite'} onClick={()=>favorite(l)}>♡ Save</button></div></div>)}</div>{!visible.length&&<p className="empty-state">No lots match these filters. Clear a filter or search a different crop.</p>}<div className="bulk"><div><PackageCheck/><div><h3>Buying in bulk?</h3><p>Request GST-ready quotes, negotiate with verified farmers, and arrange recurring contracts.</p></div></div><button className="primary" onClick={()=>setView('bulk')}>Open wholesale marketplace</button></div></section>
}
