 return <section className="page"><div className="page-top"><div><p className="eyebrow green">VERIFIED WHOLESALE MARKETPLACE</p><h1>Buy better, in bulk.</h1><p>Only farmer listings with 250 kg or more are available for wholesale RFQs. The farmer alone can confirm a sale.</p></div><button className="secondary" onClick={()=>setView('market')}>Retail marketplace</button></div><div className="tabs">{['discover','quotes','contracts','analytics','invoices'].map(x=><button className={tab===x?'selected':''} onClick={()=>setTab(x)} key={x}>{x}</button>)}</div>{tab==='discover'&&<><div className="market-tools"><input aria-label="Search wholesale listings" placeholder="Search crop, farmer or category" value={query} onChange={e=>setQuery(e.target.value)}/><select aria-label="Wholesale crop selection" value={crop} onChange={e=>setCrop(e.target.value)}><option value="">All crops</option>{cropOptions.map(name=><option key={name} value={name}>{name}</option>)}</select><select aria-label="Wholesale listing sort" value={sort} onChange={e=>setSort(e.target.value)}><option value="price">Lowest price</option><option value="quantity">Most stock</option></select></div><p className="search-note"><ShieldCheck size={16}/> Every result is a verified farmer listing with a submitted produce photo and at least 250 kg available.</p><div className="cards">{visibleLots.map(lot=><div className="product-wrap" key={lot.id}><LotCard lot={lot} onClick={()=>startQuote(lot)}/><div className="product-actions"><button onClick={()=>startQuote(lot)}>Request 250 kg+ quote</button><button onClick={()=>notify('AI grading report opened for buyer review.')}>AI quality report</button></div></div>)}</div>{!visibleLots.length&&<p className="empty-state">{eligibleLots.length?'No wholesale listings match these filters.':'No verified farmer listing currently has 250 kg available. Ask an admin to approve a qualifying farmer listing.'}</p>}</>}{tab==='quotes'&&<div className="account-panel"><h3>MSP-protected negotiation workspace</h3>{quote&&<div className="quote-card"><b>{quote.crop}, {quote.grade} · {quote.qty} kg available</b><p>Minimum request: 250 kg. {mspFor(quote.crop)?'Official MSP floor: ₹'+mspFor(quote.crop).toFixed(2)+'/kg.':'No MSP is notified for this crop; the farmer still sets the final sale decision.'}</p><label>Quantity (kg)<input min="250" max={quote.qty} type="number" value={quoteForm.quantity} onChange={e=>setQuoteForm({...quoteForm,quantity:e.target.value})}/></label><label>Your proposed price (₹/kg)<input min={mspFor(quote.crop)||1} step="0.01" type="number" value={quoteForm.price} onChange={e=>setQuoteForm({...quoteForm,price:e.target.value})}/></label><small>Submitting sends an RFQ. It never confirms a purchase without the farmer’s approval.</small><button className="primary" disabled={submitting} onClick={saveQuote}>{submitting?'Sending…':'Send MSP-safe quote'}</button></div>}<div className="quote-desk"><h3>Your wholesale RFQs</h3>{requests.length?requests.map(request=>{const latest=[...(request.bulk_quotes||[])].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))[0];return <div className="quote-request" key={request.id}><div><b>{request.crop} · {request.quantity_kg} kg</b><small>{new Date(request.created_at).toLocaleString()} · MSP floor {request.msp_per_kg?'₹'+Number(request.msp_per_kg).toFixed(2)+'/kg':'Not notified'} · {request.status}</small>{latest&&<strong>{latest.proposed_by==='farmer'?'Farmer counter':'Your offer'}: ₹{Number(latest.offered_price_per_kg).toFixed(2)}/kg · {latest.status}</strong>}</div><span className={request.status==='confirmed'?'scheduled-tick':''}>{request.status==='confirmed'?<><Check size={15}/> Confirmed</>:request.status}</span></div>}):<p className="empty-state">Select a wholesale listing to send your first RFQ. New requests appear here immediately.</p>}</div></div>}{tab==='contracts'&&<div className="account-panel"><h3>Contract orders</h3><p>Create recurring purchase agreements with quantity, grade, delivery window, pricing method and cancellation terms. Contracts require a farmer’s explicit acceptance.</p><button className="primary" onClick={()=>notify('New contract order draft created.')}>Create contract order</button></div>}{tab==='analytics'&&<div className="metric-grid"><Metric icon={<BarChart3/>} label="30-day spend" value="₹48,600" note="8% lower than previous period"/><Metric icon={<Users/>} label="Active suppliers" value="6" note="4 high-performing suppliers"/><Metric icon={<PackageCheck/>} label="Orders fulfilled" value="28" note="96% on-time performance"/><Metric icon={<BrainCircuit/>} label="Cost saving insight" value="₹4,120" note="From negotiated seasonal lots"/></div>}{tab==='invoices'&&<div className="account-panel"><h3>GST-compliant invoice centre</h3><p>Generated invoices include supplier and buyer GSTIN, line items, tax breakdown, warehouse handoff and order references.</p><button className="primary" onClick={()=>notify('GST invoice generation will be enabled after a farmer confirms an RFQ.')}>Generate invoice</button></div>}</section>
