function IntakeQrScanner({crops,onClose,onCropDetected,onConfirm}){const videoRef=useRef(null),streamRef=useRef(null),[status,setStatus]=useState('Opening the rear camera…'),[code,setCode]=useState('');useEffect(()=>{let active=true,frame;const stop=()=>{if(frame)cancelAnimationFrame(frame);streamRef.current?.getTracks().forEach(track=>track.stop())};const useCode=value=>{if(!active||!value)return;setCode(value);const found=crops.find(crop=>value.toLowerCase().includes(crop.toLowerCase()));if(found)onCropDetected(found);setStatus(found?'QR scanned. Crop set to '+found+'.':'QR scanned. Confirm the crop selection before creating the lot.')};const start=async()=>{try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});if(!active){stream.getTracks().forEach(track=>track.stop());return}streamRef.current=stream;videoRef.current.srcObject=stream;await videoRef.current.play();if(!('BarcodeDetector' in window)){setStatus('Camera is open. This browser cannot decode QR codes automatically; use a Chrome/Edge mobile browser or enter the crop manually.');return}const detector=new window.BarcodeDetector({formats:['qr_code']});const scan=async()=>{if(!active)return;try{const codes=await detector.detect(videoRef.current);if(codes[0]?.rawValue){useCode(codes[0].rawValue);return}}catch{}frame=requestAnimationFrame(scan)};setStatus('Point the camera at the intake QR code.');scan()}catch{setStatus('Camera permission was blocked or unavailable. Allow camera access, then try again.')}};start();return()=>{active=false;stop()}},[crops,onCropDetected]);return <div className="modal-back"><div className="modal qr-scanner"><button className="close" onClick={onClose}><X/></button><p className="eyebrow green">INTAKE QR SCAN</p><h2>Scan before creating the lot</h2><video ref={videoRef} autoPlay muted playsInline/><p>{status}</p>{code&&<code>{code}</code>}<div className="modal-actions"><button className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={!code} onClick={onConfirm}><Check size={18}/>Create verified lot</button></div></div></div>}
function WarehouseOrders({orders,activeWarehouse,notify,setLiveTick}){const relevant=orders.filter(order=>order.pickupWarehouse===activeWarehouse);const markReady=async order=>{if(!order.dbId){notify('This demo order is already visible in the selected warehouse queue.');return}const {error}=await supabase.from('consumer_orders').update({status:'ready_for_pickup'}).eq('id',order.dbId);if(error){notify(error.message);return}setLiveTick(tick=>tick+1);notify('Order marked ready. The warehouse, admin and consumer views are now synced.');};return <QueuePanel title={'Consumer pickup orders · '+activeWarehouse} empty="No pickup orders assigned to this warehouse yet." items={relevant} render={order=><><b>{order.id} · {order.quantity} kg</b><small>{order.consumerName} · {order.consumerAddress} · {order.items} lot(s) · {order.status}</small>{String(order.status).toLowerCase()==='ready for pickup'?<span className="scheduled-tick"><Check size={15}/> Ready for pickup</span>:<button className="queue-action" onClick={()=>markReady(order)}>Mark ready</button>}</>}/>}
